// Recursive function to generate Fibonacci sequence
unsigned long long fibonacci(int n, unsigned long long a, unsigned long long b) {
    if (n == 0) return 0;
    else if (n == 1) return a;
    else return fibonacci(n - 1, b, a + b);
}

