let homophones = ["is": "are", "weigh": "weight", "sea": "see", "know": "no", "too": "to", "no": "not", "sum": "some", "right": "write"]

func replaceHomophones(_ text: String) -> String {
    var result = ""

    // Loop through the text and replace homophones
    for (index, char) in text.enumerated() {
        let wordStart = text.index(text.startIndex, offsetBy: index)
        let currentWordEnd = text.distance(from: wordStart, to: text[...].firstIndex({ $0 == char && !$0.isWhitespace })) ?? text.endIndex
        let currentWord = String(text[wordStart..<currentWordEnd])

        // Check if current word contains any homophones
        for (homophone, replacement) in homophones {
            if currentWord.lowercased().range(of: homophone, options: .regularExpression) != nil {
                result += String(text[wordStart..<wordStart], repeating: space)
                result += String(repeating: replacement, count: Int(currentWordEnd - wordStart))
                break // Exit loop since we found a homophone
            }
        }

        // If no homophones were found, add the current character
        result += String(char)
    }

    return result
}

