function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];

        if ($ageA == $ageB) {
            return 0; // If ages are equal, don't change order
        }

        return $order === 'ASC' ? $ageA < $ageB : $ageA > $ageB; // Return correct order based on $order parameter
    });

    return $set;
}
```

