function findEntriesByKey(obj, keyPath, value) {
  let result = [];

  // Split the key path into an array of keys
  const keys = keyPath.split(".");

  // Iterate over the object and its nested properties
  for (let prop in obj) {
    let curObj = obj[prop];

    // Check if we've reached the last key in the path
    if (keys.length === 1) {
      // If so, check if the current value matches the given one
      if (curObj === value || (typeof curObj === "object" && curObj !== null && JSON.stringify(curObj) === JSON.stringify(value))) {
        result.push({ [prop]: curObj });
      }
    } else {
      // If not, continue recursively with the nested property
      const nextProp = keys.shift();

      if (curObj[nextProp] !== undefined) {
        curObj = curObj[nextProp];

        // Recursively call the function again with the remaining keys and the new object
        const subResult = findEntriesByKey(curObj, keys.join("."), value);

        // Add the results to our overall list
        result = result.concat(subResult);
      }

      // Clean up and move on
      keys.push(nextProp);
      curObj = obj[prop];
    }
  }

  // Return the final result
  return result;
}
```

This function takes three arguments: `obj`, which is the main object to search through; `keyPath`, which is a string representing the path to the nested key we're looking for (e.g. "person.address.city"); and `value`, which is the value that the key should match.

The function returns an array containing objects representing each entry found in the nested structure that matches the specified key and value. The objects themselves contain only the matched key-value pairs, as specified by the `prop` parameter passed to the function during each iteration.

